int lengthOfLIS(int[] a) {
    int n = a.length, best = 0;
    int[] dp = new int[n];
    Arrays.fill(dp, 1);                   // each element alone has length 1
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < i; j++)
            if (a[j] < a[i])
                dp[i] = Math.max(dp[i], dp[j] + 1);
        best = Math.max(best, dp[i]);
    }
    return best;
}

