    vector<int> tails;
    for (int x : a) {
        auto it = lower_bound(tails.begin(), tails.end(), x);
        if (it == tails.end()) tails.push_back(x);   // x extends the LIS
        else *it = x;                                 // keep tails small
    }
    return tails.size();
}

