function lengthOfLIS(a) {
  const tails = [];
  for (const x of a) {
    let lo = 0, hi = tails.length;
    while (lo < hi) {                 // binary search for first tail >= x
      const mid = (lo + hi) >> 1;
      if (tails[mid] < x) lo = mid + 1; else hi = mid;
    }
    if (lo === tails.length) tails.push(x); // x extends the LIS
    else tails[lo] = x;                      // keep tails small
  }
  return tails.length;
}
